"""KinDER instance i00 controller record; all simulator access uses rcb_client."""
import numpy as np
from rcb_client import Robot

r = Robot()
LAYOUT = ["base_x", "base_y", "base_yaw", "arm_1", "arm_2", "arm_3",
          "arm_4", "arm_5", "arm_6", "arm_7", "gripper"]

def status():
    return r.status()

def observe(cameras=None, depth=False):
    return r.get_obs(cameras=cameras, include_depth=depth)

def step(rows, cameras=None, video="none", depth=False, note=""):
    return r.submit("delta", np.asarray(rows, dtype=np.float32).reshape(-1, 11),
                    cameras=cameras, video=video, include_depth=depth, note=note)

def hold(n, gripper=None, cameras=None, depth=False, note=""):
    """Hold the current arm/base targets for n control steps."""
    a = np.zeros((n, 11), dtype=np.float32)
    if gripper is not None:
        a[:, 10] = gripper
    return step(a, cameras=cameras, depth=depth, note=note)

def ramp(n, changes, gripper=None, cameras=None, depth=False, note=""):
    """Repeat per-step delta commands; changes maps action-layout names to values."""
    a = np.zeros((n, 11), dtype=np.float32)
    for name, value in changes.items():
        a[:, LAYOUT.index(name)] = value
    if gripper is not None:
        a[:, 10] = gripper
    return step(a, cameras=cameras, depth=depth, note=note)

if __name__ == "__main__":
    print(r.spec())
    print(r.status())
